import{_ as i,c as r,o,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"ENFORCING COMMONSENSE RULES OF THE ROAD","description":"","frontmatter":{"title":"ENFORCING COMMONSENSE RULES OF THE ROAD","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/enforcing-commonsense-rules-of-the-road-for-americas-truck-drivers/","publishDate":"2025-04-28T18:16:27-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-28-enforcing-commonsense-rules-of-the-road.md","filePath":"executive-orders/2025-04-28-enforcing-commonsense-rules-of-the-road.md"}'),s={name:"executive-orders/2025-04-28-enforcing-commonsense-rules-of-the-road.md"};function t(a,e,c,l,d,u){return o(),r("div",null,e[0]||(e[0]=[n('<h1 id="enforcing-commonsense-rules-of-the-road" tabindex="-1">ENFORCING COMMONSENSE RULES OF THE ROAD <a class="header-anchor" href="#enforcing-commonsense-rules-of-the-road" aria-label="Permalink to &quot;ENFORCING COMMONSENSE RULES OF THE ROAD&quot;">​</a></h1><p>Published: Monday, April 28, 2025</p><ul><li>The executive order emphasizes the essential role of truck drivers in the U.S. economy and public safety.</li><li>Proficiency in English is mandated as a non-negotiable safety requirement for commercial drivers to ensure safe communication.</li><li>Federal law requires drivers to be able to read and speak English sufficiently to follow road signs, respond to inquiries, and complete necessary records; this requirement has been historically unenforced, affecting roadway safety.</li><li>The Administration plans to enforce English-language proficiency requirements and remove unnecessary regulatory burdens affecting truck drivers&#39; working conditions.</li><li>The Secretary of Transportation is tasked with specific actions: <ul><li>Rescind outdated English language proficiency guidelines and issue new compliance inspection procedures within 60 days.</li><li>Revise out-of-service criteria to ensure drivers lacking English proficiency are prohibited from operating vehicles.</li><li>Review non-domiciled commercial driver’s licenses for any irregularities and improve verification of driving credentials.</li><li>Identify additional regulatory actions to enhance truck drivers&#39; working conditions within 60 days.</li></ul></li><li>Clauses specify that the order does not alter existing agency authority or create enforceable rights against the U.S. government.</li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/enforcing-commonsense-rules-of-the-road-for-americas-truck-drivers/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/enforcing-commonsense-rules-of-the-road-for-americas-truck-drivers/</a></p>',4)]))}const m=i(s,[["render",t]]);export{h as __pageData,m as default};
